<?php
namespace App\Http\Controllers;
use App\Http\Requests\SupplierRequest; use App\Models\Supplier; use Illuminate\Http\Request;
class SupplierController extends Controller { public function index(Request $request){$suppliers=Supplier::query()->when($request->search,fn($q,$s)=>$q->where(fn($q)=>$q->where('name','like',"%$s%")->orWhere('email','like',"%$s%")))->latest()->paginate(15)->withQueryString();return view('resources.index',compact('suppliers'))->with('resource','suppliers');} public function create(){return view('resources.form',['resource'=>'suppliers','record'=>new Supplier]);} public function store(SupplierRequest $request){Supplier::create($request->validated());return redirect()->route('suppliers.index')->with('success','Supplier created.');} public function edit(Supplier $supplier){return view('resources.form',['resource'=>'suppliers','record'=>$supplier]);} public function update(SupplierRequest $request,Supplier $supplier){$supplier->update($request->validated());return redirect()->route('suppliers.index')->with('success','Supplier updated.');} public function destroy(Supplier $supplier){$supplier->delete();return back()->with('success','Supplier deleted.');} }
